            transcript = replayRunner.transcript();
            Gdx.app.exit();
        }
    }

    public Transcript getTranscript() {
        if (failure != null) {
            throw failure;
        }
        if (transcript == null) {
            throw new IllegalStateException("Replay did not produce a transcript");
        }
        return transcript;
    }

    private void fail(RuntimeException exception) {
        failure = exception;
        Gdx.app.exit();
    }
}

