        if (tick < 0) {
            throw new IllegalArgumentException("Tick must be non-negative");
        }
        this.tick = tick;
        this.playerId = playerId;
        this.command = command;
    }

    public int getTick() {
        return tick;
    }

    public int getPlayerId() {
        return playerId;
    }

